using System.CommandLine;
using System.CommandLine.Help;
using System.CommandLine.Parsing;

namespace Hoboman.Cli;

internal sealed class CommandLine
{
    private readonly RootCommand _rootCommand = new("Send Hoboman requests without opening the GUI.");
    private readonly Command _listCommand = new("list", "List saved request paths.");
    private readonly Command _sendCommand = new("send", "Send a saved request or a method and URL.");
    private readonly Argument<string[]> _targetArgument = new("request-or-method-url") { Arity = new(1, 2) };
    private readonly Option<string> _environmentOption = new("--env") { Description = "Select an environment." };
    private readonly Option<string[]> _headersOption = new("-H") { Description = "Add a direct request header: Name: Value.", Arity = ArgumentArity.OneOrMore, AllowMultipleArgumentsPerToken = false };
    private readonly Option<string> _jsonOption = new("--json") { Description = "Direct JSON body: text, @file or @@literal." };
    private readonly Option<string> _textOption = new("--text") { Description = "Direct text body: text, @file or @@literal." };
    private readonly Option<bool> _bodyVariablesOption = new("--body-vars") { Description = "Use environment variables in the direct body.", Arity = ArgumentArity.Zero };
    private readonly Option<string[]> _variablesOption = new("--var") { Description = "Set a temporary variable: name=value.", Arity = ArgumentArity.OneOrMore, AllowMultipleArgumentsPerToken = false };
    private readonly Option<string> _variablesFileOption = new("--vars") { Description = "Read string variables from a JSON file or redirected stdin (-)." };

    public CommandLine()
    {
        _rootCommand.Directives.Clear();
        _rootCommand.Subcommands.Add(_listCommand);
        _rootCommand.Subcommands.Add(_sendCommand);
        _sendCommand.Arguments.Add(_targetArgument);
        foreach (var option in new Option[] { _environmentOption, _headersOption, _jsonOption, _textOption, _bodyVariablesOption, _variablesOption, _variablesFileOption }) _sendCommand.Options.Add(option);
    }

    public CommandInput Parse(string[] arguments)
    {
        var result = _rootCommand.Parse(arguments, new() { ResponseFileTokenReplacer = null });
        if (result.Errors.Count > 0 || result.Tokens.Any(token => token.Type == TokenType.Directive)) return Invalid();
        if (result.Action is HelpAction || result.Action == _rootCommand.Options.OfType<VersionOption>().Single().Action) return new(StandardOutput: result);
        if (result.CommandResult.Command == _listCommand) return new(IsList: true);
        if (result.CommandResult.Command != _sendCommand) return Invalid();
        if (new Option[] { _environmentOption, _jsonOption, _textOption, _bodyVariablesOption, _variablesFileOption }.Any(option => result.GetResult(option)?.IdentifierTokenCount > 1)) return Invalid();
        var targetTokens = result.GetResult(_targetArgument)!.Tokens;
        if (result.Tokens.TakeWhile(token => token.Type != TokenType.DoubleDash).Any(token => token.Value.StartsWith('-') && targetTokens.Any(targetToken => ReferenceEquals(targetToken, token)))) return Invalid();

        var targets = result.GetValue(_targetArgument)!;
        var jsonBody = result.GetValue(_jsonOption);
        var textBody = result.GetValue(_textOption);
        var useBodyVariables = result.GetValue(_bodyVariablesOption);
        if (jsonBody is not null && textBody is not null) return Invalid();
        if (useBodyVariables && jsonBody is null && textBody is null) return Invalid();
        if (targets.Length == 1 && (result.GetResult(_headersOption) is { Implicit: false } || jsonBody is not null || textBody is not null || result.GetResult(_bodyVariablesOption) is { Implicit: false })) return Invalid();

        return new(Send: new(targets, result.GetValue(_environmentOption), result.GetValue(_headersOption) ?? [], jsonBody, textBody, useBodyVariables, result.GetValue(_variablesOption) ?? [], result.GetValue(_variablesFileOption)));
    }

    private static CommandInput Invalid() => new(Problem: "Invalid command arguments. Use --help for usage.");
}

internal sealed record CommandInput(SendInput? Send = null, bool IsList = false, System.CommandLine.ParseResult? StandardOutput = null, string? Problem = null);
internal sealed record SendInput(string[] Target, string? EnvironmentName, string[] Headers, string? JsonBody, string? TextBody, bool UseBodyVariables, string[] Variables, string? VariablesFile)
{
    public bool IsDirect => Target.Length == 2;
}

