using System.CommandLine;
using Hoboman.Cli;

namespace Hoboman.Tests.Cli;

public sealed class CommandLineTests
{
    [Fact]
    public void Parse_WhenListing_ThenSelectsList()
    {
        var input = new CommandLine().Parse(["list"]);

        Assert.True(input.IsList);
        Assert.Null(input.Send);
        Assert.Null(input.Problem);
    }

    [Theory]
    [InlineData("GET")]
    [InlineData("Folder/My request")]
    public void Parse_WhenThereIsOneTarget_ThenSelectsSavedRequest(string name)
    {
        var input = new CommandLine().Parse(["send", name, "--env", "Dev", "--var", "a=first", "--var", "a=last", "--vars", "-"]);

        Assert.Null(input.Problem);
        var send = Assert.IsType<SendInput>(input.Send);
        Assert.False(send.IsDirect);
        Assert.Equal([name], send.Target);
        Assert.Equal("Dev", send.EnvironmentName);
        Assert.Equal(["a=first", "a=last"], send.Variables);
        Assert.Equal("-", send.VariablesFile);
    }

    [Fact]
    public void Parse_WhenThereAreTwoTargets_ThenPreservesDirectInput()
    {
        var input = new CommandLine().Parse(["send", "CUSTOM", "https://localhost/{{id}}", "-H", "First: one", "-H", "First: two", "--json", "{\"id\":\"{{id}}\"}", "--body-vars", "--var", "id=Ærø"]);

        Assert.Null(input.Problem);
        var send = Assert.IsType<SendInput>(input.Send);
        Assert.True(send.IsDirect);
        Assert.Equal(["CUSTOM", "https://localhost/{{id}}"], send.Target);
        Assert.Equal(["First: one", "First: two"], send.Headers);
        Assert.Equal("{\"id\":\"{{id}}\"}", send.JsonBody);
        Assert.True(send.UseBodyVariables);
        Assert.Equal(["id=Ærø"], send.Variables);
    }

    [Theory]
    [InlineData("--json", "@file")]
    [InlineData("--text", "@@literal")]
    [InlineData("--json", "")]
    public void Parse_WhenBodyIsProvided_ThenPreservesItsText(string option, string body)
    {
        var input = new CommandLine().Parse(["send", "POST", "https://localhost/", option, body]);

        Assert.Null(input.Problem);
        Assert.Equal(body, option == "--json" ? input.Send!.JsonBody : input.Send!.TextBody);
        Assert.False(input.Send.UseBodyVariables);
    }

    [Fact]
    public async Task Parse_WhenResponseFileExists_ThenDoesNotExpandIt()
    {
        using var folder = new TemporaryFolder();
        Directory.CreateDirectory(folder.Path);
        var path = Path.Combine(folder.Path, "body.json");
        await File.WriteAllTextAsync(path, "--help --env sentinel-secret", TestContext.Current.CancellationToken);

        var input = new CommandLine().Parse(["send", "POST", "https://localhost/", "--json", $"@{path}"]);

        Assert.Null(input.Problem);
        Assert.Null(input.StandardOutput);
        Assert.Equal($"@{path}", input.Send!.JsonBody);
    }

    [Theory]
    [InlineData(new string[] { "send", "--", "-MinRequest" }, false, "-MinRequest", null)]
    [InlineData(new string[] { "send", "--", "-GET", "https://localhost/" }, true, "-GET", "https://localhost/")]
    [InlineData(new string[] { "send", "--", "GET", "-url" }, true, "GET", "-url")]
    [InlineData(new string[] { "send", "--", "--help" }, false, "--help", null)]
    [InlineData(new string[] { "send", "--env", "-same", "--", "-same" }, false, "-same", null)]
    public void Parse_WhenOptionsAreTerminated_ThenPreservesTargets(string[] arguments, bool direct, string first, string? second)
    {
        var input = new CommandLine().Parse(arguments);

        Assert.Null(input.Problem);
        Assert.Null(input.StandardOutput);
        Assert.Equal(direct, input.Send!.IsDirect);
        Assert.Equal(second is null ? [first] : [first, second], input.Send.Target);
    }

    [Theory]
    [InlineData]
    [InlineData("unknown", "sentinel-secret")]
    [InlineData("send")]
    [InlineData("send", "GET", "https://localhost/", "extra")]
    [InlineData("send", "--", "GET", "https://localhost/", "extra")]
    [InlineData("list", "--env", "sentinel-secret")]
    [InlineData("send", "saved", "--unknown", "sentinel-secret")]
    [InlineData("send", "saved", "--unknown")]
    [InlineData("send", "--unknown", "--", "saved")]
    [InlineData("send", "saved", "-H", "Authorization: sentinel-secret")]
    [InlineData("send", "saved", "--json", "sentinel-secret")]
    [InlineData("send", "saved", "--text", "sentinel-secret")]
    [InlineData("send", "saved", "--body-vars")]
    [InlineData("send", "GET", "https://localhost/", "--body-vars")]
    [InlineData("send", "POST", "https://localhost/", "--json", "sentinel-secret", "--text", "text")]
    [InlineData("[diagram]", "send", "saved", "--var", "key=sentinel-secret")]
    public void Parse_WhenInputIsInvalid_ThenReturnsOnlyControlledProblem(params string[] arguments)
    {
        var input = new CommandLine().Parse(arguments);

        Assert.Equal("Invalid command arguments. Use --help for usage.", input.Problem);
        Assert.Null(input.Send);
        Assert.Null(input.StandardOutput);
        Assert.False(input.IsList);
        Assert.DoesNotContain("sentinel-secret", input.Problem);
    }

    [Theory]
    [InlineData("--env")]
    [InlineData("--json")]
    [InlineData("--text")]
    [InlineData("--vars")]
    public void Parse_WhenSingletonOptionIsMissingOrRepeated_ThenReturnsControlledProblem(string option)
    {
        var parser = new CommandLine();

        Assert.NotNull(parser.Parse(["send", "POST", "https://localhost/", option]).Problem);
        Assert.NotNull(parser.Parse(["send", "POST", "https://localhost/", option, "sentinel-secret", option, "second"]).Problem);
    }

    [Theory]
    [InlineData("-H")]
    [InlineData("--var")]
    public void Parse_WhenRepeatableOptionHasNoValue_ThenReturnsControlledProblem(string option)
    {
        Assert.NotNull(new CommandLine().Parse(["send", "GET", "https://localhost/", option]).Problem);
        Assert.NotNull(new CommandLine().Parse(["send", "GET", "https://localhost/", option, option, "sentinel-secret"]).Problem);
    }

    [Fact]
    public void Parse_WhenBodyFlagIsRepeated_ThenReturnsControlledProblem()
    {
        Assert.NotNull(new CommandLine().Parse(["send", "POST", "https://localhost/", "--json", "{}", "--body-vars", "--body-vars"]).Problem);
    }

    [Theory]
    [InlineData(new string[] { "--help" }, "Commands:")]
    [InlineData(new string[] { "send", "--help" }, "--json")]
    [InlineData(new string[] { "list", "--help" }, "List saved request paths.")]
    [InlineData(new string[] { "--version" }, "1.0.0")]
    public void Parse_WhenHelpOrVersionIsRequested_ThenUsesStandardTextOutput(string[] arguments, string expected)
    {
        using var output = new StringWriter();
        using var error = new StringWriter();
        var input = new CommandLine().Parse(arguments);

        Assert.Null(input.Problem);
        Assert.NotNull(input.StandardOutput);
        var exitCode = input.StandardOutput.Invoke(new InvocationConfiguration { Output = output, Error = error });

        Assert.Equal(0, exitCode);
        Assert.Contains(expected, $"{output}");
        Assert.Equal("", $"{error}");
        Assert.Null(input.Send);
        Assert.False(input.IsList);
    }
}

